from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}


def _plan_active(member: dict, base: int) -> tuple[int | None, str]:
    return base, "renewed"


def _plan_lapsed(member: dict, base: int) -> tuple[int | None, str]:
    if "expired_days" not in member or not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
        return None, "bad expiry"
    if member["expired_days"] <= GRACE_DAYS:
        return base + LATE_FEE, "renewed"
    return base + REINSTATE_SURCHARGE, "reinstated"


